# widget host: lifecycle + error boundaries per widget
widgets = [
    {'name': 'cpu', 'render': lambda: 'CPU 42%', 'refresh': 5},
    {'name': 'broken', 'render': lambda: 1/0, 'refresh': 5},
]

for w in widgets:
    try:
        print('%-8s -> %s (refresh %ss)' % (w['name'], w['render'](), w['refresh']))
    except Exception as e:
        print('%-8s -> ERROR CARD (%s): dashboard survives' % (w['name'], e))
