# 12-col grid: snap, resize, collision push-down
COLS = 12
widgets = {'a': {'x': 0, 'y': 0, 'w': 6, 'h': 2}, 'b': {'x': 6, 'y': 0, 'w': 6, 'h': 2}}

def collides(p, q):
    return not (p['x']+p['w'] <= q['x'] or q['x']+q['w'] <= p['x'] or
                p['y']+p['h'] <= q['y'] or q['y']+q['h'] <= p['y'])

def move(name, nx):
    widgets[name]['x'] = max(0, min(nx, COLS - widgets[name]['w']))  # snap+clamp
    for other, w in widgets.items():
        if other != name and collides(widgets[name], w):
            w['y'] = widgets[name]['y'] + widgets[name]['h']  # push down

move('a', 5)
for n, w in widgets.items():
    print('%-2s x=%d y=%d w=%d h=%d' % (n, w['x'], w['y'], w['w'], w['h']))
print('snap + clamp + push-down: the whole interaction model')

# responsive reflow: same order, arrangement changes per breakpoint
widgets = ['cpu', 'memory', 'disk', 'network']

def reflow(width):
    cols = 12 if width >= 1200 else 6 if width >= 768 else 1
    rows, row = [], []
    for w in widgets:
        row.append(w)
        if len(row) >= cols // 3:
            rows.append(row); row = []
    if row:
        rows.append(row)
    return cols, rows

for width in (1400, 800, 400):
    cols, rows = reflow(width)
    print('width %4d (%2d cols): %s' % (width, cols, rows))
print('order stable; arrangement reflows (never just shrinks)')

import hashlib, time, urllib.parse

SECRET = 's3cret'

def share_link(dashboard, filters, ttl=3600):
    params = {'dash': dashboard, 'filters': ','.join('%s=%s' % f for f in filters),
              'exp': int(time.time()) + ttl}
    sig = hashlib.sha256((SECRET + str(sorted(params.items()))).encode()).hexdigest()[:16]
    params['sig'] = sig
    return 'https://dash.example/d?' + urllib.parse.urlencode(params)

print(share_link('ops', [('region', 'us-east')]))
print('state in URL (deep-linkable); signed + expirable; role-based widgets')

