from collections import defaultdict

widget_queries = {'w1': 'q(a)', 'w2': 'q(a)', 'w3': 'q(b)', 'w4': 'q(a)'}
by_query = defaultdict(list)
for w, q in widget_queries.items():
    by_query[q].append(w)

print('widgets: %d, unique queries: %d' % (len(widget_queries), len(by_query)))
for q, ws in by_query.items():
    print('  execute %s once -> serve %s' % (q, ws))
