import json

template = {'title': '$svc overview',
            'widgets': [{'query': 'errors{svc="$svc"}'}]}

def instantiate(tpl, svc):
    s = json.dumps(tpl).replace('$svc', svc)
    return json.loads(s)

for svc in ('api', 'worker'):
    d = instantiate(template, svc)
    print('%-7s -> %s | %s' % (svc, d['title'], d['widgets'][0]['query']))
print('one template, N instances; templates in git, applied by CI')
